// pdb params: apDebugText, aeLocation, aeJustify
void MvProcedure::FUN_007dace0(MvDisplay* display, int x, int y)
{
    switch (m_eState)
    {
    case 0:
        display->Print(x, y, "INITIALIZING");
        break;
    case 1:
        display->Print(x, y, "MOVING");
        break;
    case 2:
        display->Print(x, y, "MOVING_USING_COVER");
        display->Print(x, y, "Check Cover Timer: %.02f/%.02f", m_kCoverTimer.GetElapsed(), m_kCoverTimer.GetTargetTime());
        break;
    case 3:
        display->Print(x, y, "HIDING_BEHIND_COVER");
        display->Print(x, y, "Hiding Timer: %.02f/%.02f", m_kHideTimer.GetElapsed(), m_kHideTimer.GetTargetTime());
        display->Print(x, y, "Check Cover Timer: %.02f/%.02f", m_kCoverTimer.GetElapsed(), m_kCoverTimer.GetTargetTime());
        break;
    }
    MvPoint position = m_kDest.GetPos();
    MvReference* cell = m_kDest.GetCell();
    if (cell && cell != m_pkController->GetFieldBC()->FUN_004e8810())
        display->Print(x, y, "Destination: %s (%.02f,%.02f,%.02f)", cell->GetDebugName(), position.x, position.y,
                       position.z);
    else
        display->Print(x, y, "Destination: (%.02f,%.02f,%.02f)", position.x, position.y, position.z);
    if (m_pkTarget)
    {
        MvPoint targetPosition = m_pkTarget->GetDebugPosition();
        display->Print(x, y, "Target: '%s' (%08X) - Position: (%.02f,%.02f,%.02f)",
                       m_pkTarget->GetEditorIDLength() ? m_pkTarget->GetDebugName() : m_pkTarget->FUN_004e9a10(),
                       m_pkTarget->m_uiFormID, targetPosition.x, targetPosition.y, targetPosition.z);
    }
    if (m_kDestTimer.IsSet())
        display->Print(x, y, "Check Destination Timer: %.02f/%.02f", m_kDestTimer.GetElapsed(),
                       m_kDestTimer.GetTargetTime());
}

